import math

def check_n(n):
    """Checks if k^2 = 1 (mod n) for all k coprime to n."""
    if n == 1:
        # Although the problem asks for n >= 2, good practice to handle n=1
        return True

    # We only need to check k in the range 1 <= k < n
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check the condition k^2 - 1 is a multiple of n, i.e., k^2 = 1 (mod n)
            if (k * k - 1) % n != 0:
                # Found a counterexample
                return False
    # If the loop completes without returning False, the condition holds for all coprime k
    return True

results = {}
for n in range(2, 21):
    is_solution = check_n(n)
    results[n] = is_solution

# Prepare output for notes.md
output = "Brute-force verification results for n=2 to n=20:\n"
for n, is_sol in results.items():
    status = "SUCCESS (Solution)" if is_sol else "FAILURE"
    output += f"n={n}: {status}\n"

print(output)
